fn broadcast_arrays(a: Vec<i8>, b: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    let len_a = a.len();
    let len_b = b.len();
    let max_len = len_a.max(len_b);

    let mut output_a = Vec::with_capacity(max_len);
    let mut output_b = Vec::with_capacity(max_len);

    if len_a == 1 {
        // If a has length 1, repeat its value to fill output_a
        output_a.extend(std::iter::repeat(a[0]).take(max_len));
    } else {
        // If a has length greater than 1, copy it directly
        output_a.extend(&a);
    }

    if len_b == 1 {
        // If b has length 1, repeat its value to fill output_b
        output_b.extend(std::iter::repeat(b[0]).take(max_len));
    } else {
        // If b has length greater than 1, copy it directly
        output_b.extend(&b);
    }

    (output_a, output_b)
}